const juAutoTransparencyShaderGuid = 'd20272b3c7d3d5b40bd5ef601dc742a4';
const juTransparencyAdapter = 'ju-auto-transparency-v1';
const juTransparencyShaderTarget = 'three-webgl-r180';

function applyJuTransparencyShader(material) {
  if (material.userData.unityShaderGuid !== juAutoTransparencyShaderGuid) return;
  const adapter = material.userData.shaderAdapter;
  const target = material.userData.shaderTarget;
  if (adapter && adapter !== juTransparencyAdapter || target && target !== juTransparencyShaderTarget
    || THREE.REVISION !== '180') {
    reportUnsupportedUnityAPI(`Material shader adapter ${adapter ?? 'legacy'} for ${target ?? 'legacy'}`, {
      system: 'rendering', detail: `Requires ${juTransparencyAdapter} on ${juTransparencyShaderTarget}` });
    return;
  }
  // Shader Graph uses the sampled RGB for BaseColor, but takes Alpha only from
  // its separate alpha property. Three r180's map chunk multiplies RGBA.
  material.onBeforeCompile = shader => {
    const mapInclude = '#include <map_fragment>';
    const mapProduct = 'diffuseColor *= sampledDiffuseColor;';
    const mapChunk = THREE.ShaderChunk.map_fragment;
    if (!shader.fragmentShader.includes(mapInclude) || !mapChunk.includes(mapProduct)) {
      reportUnsupportedUnityAPI('JU Auto Transparency map shader patch', {
        system: 'rendering', detail: 'Three map chunk changed; using standard alpha fallback' });
      return;
    }
    shader.fragmentShader = shader.fragmentShader.replace(mapInclude, mapChunk.replace(
      mapProduct, 'diffuseColor.rgb *= sampledDiffuseColor.rgb;'));
  };
}

